// Renders docs/architecture.svg — the README's architecture diagram — from
// site.config.json, so the picture always shows THIS instance: its name, ZIP,
// publish day, URL, and whether a feedback inbox is configured.
//
// Why a generator instead of a checked-in image: the reference implementation
// kept a hand-refreshed PNG and it went stale within days. A derived artifact
// must be regenerated by machinery, not by habit — /setup runs this after
// writing config, and the weekly workflow re-renders it before committing, so
// the diagram cannot silently drift from the config it describes.
//
// Deterministic on purpose (no dates, no randomness): same config → same bytes,
// so `git diff` on the SVG means the architecture description actually changed.
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, loadConfig, displayName } from './lib/config.mjs';

const cfg = loadConfig();

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Overflow guard, in the spirit of the reference's render script: a label that
// outgrows its box becomes unreadable in the README, so fail loudly instead.
const MAX = 46;
function line(s) {
  if (s.length > MAX) {
    console.error(`render-architecture: label overflows its box (${s.length} > ${MAX} chars):\n  "${s}"`);
    console.error('Shorten the config value (siteName/domain/workerName) or the label.');
    process.exit(1);
  }
  return esc(s);
}

const name = displayName(cfg);
const url = cfg.domain || `${cfg.workerName}.<account>.workers.dev`;
const inbox = !!cfg.contactEmail;

// Truncate long values rather than overflow — the diagram is a map, not a record.
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const title = trunc(`${name} — how ZIP ${cfg.zip} gets its weekly brief`, 78);
const urlShort = trunc(url, 40);

// Layout constants. Three lanes, fixed geometry; every text line is guarded.
const W = 1120, LANE_W = 330, LANE_GAP = 30, LANE_Y = 78, PAD = 25;
const laneX = i => PAD + i * (LANE_W + LANE_GAP);

const ink = '#1a1a1a', paper = '#fbfaf7', rule = '#c9c4b8',
      accent = cfg.colors?.accent || '#7a2e2e';

const lanes = [
  {
    head: '1 · YOUR MACHINE — Claude Code',
    rows: [
      ['/setup', 'interview → config, privacy patterns'],
      ['/find-sources', 'discover · vet · approve sources'],
      ['/first-issue', 'prove the pipeline locally'],
      ['/go-live', 'connect GitHub + Cloudflare'],
      ['/add-source', 'grow the registry over time'],
    ],
    foot: 'git push ▸',
  },
  {
    head: `2 · GITHUB — private repo (Actions)`,
    rows: [
      [`${cfg.publishDay} cron`, 'fetch-data — adapters, no guessing'],
      ['write issue', 'the ONLY model step (Claude default)'],
      ['gates', 'privacy-scan · verify-issue — or no publish'],
      ['then', 'normalize → PDF → build → addendum'],
      ['watchdogs', 'smoke · publication-check · sources'],
    ],
    foot: 'commit to main = the deploy trigger ▸',
  },
  {
    head: `3 · CLOUDFLARE — ${trunc(cfg.domain || 'workers.dev (free)', 24)}`,
    rows: [
      ['Workers Builds', 'watches main on every push'],
      ['build + deploy', 'node build.mjs → wrangler deploy'],
      ['readers get', 'HTML · PDF · RSS — no JS, no tracking'],
      ['site', urlShort],
      inbox
        ? ['feedback', `inbox (not a mailing list) → /add-source`]
        : ['feedback', 'no inbox configured (optional)'],
    ],
    foot: '',
  },
];

const ROW_H = 44, HEAD_H = 34, LANE_H = HEAD_H + lanes[0].rows.length * ROW_H + 14;
const H = LANE_Y + LANE_H + 96;

let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Architecture diagram">
<style>
  text { font-family: Georgia, 'Times New Roman', serif; fill: ${ink}; }
  .mono { font-family: ui-monospace, Menlo, Consolas, monospace; }
  .h { font-size: 15px; font-weight: bold; fill: ${accent}; letter-spacing: .4px; }
  .k { font-size: 14px; font-weight: bold; }
  .v { font-size: 13px; fill: #444; }
  .t { font-size: 19px; font-weight: bold; }
  .cap { font-size: 13.5px; font-style: italic; fill: #444; }
  .foot { font-size: 13px; font-weight: bold; fill: ${accent}; }
</style>
<rect width="${W}" height="${H}" fill="${paper}"/>
<text class="t" x="${PAD}" y="34">${esc(title)}</text>
<line x1="${PAD}" y1="46" x2="${W - PAD}" y2="46" stroke="${accent}" stroke-width="2"/>
`;

lanes.forEach((lane, i) => {
  const x = laneX(i);
  svg += `<rect x="${x}" y="${LANE_Y}" width="${LANE_W}" height="${LANE_H}" fill="#ffffff" stroke="${rule}" rx="6"/>
<text class="h mono" x="${x + 14}" y="${LANE_Y + 23}">${line(lane.head)}</text>
<line x1="${x + 12}" y1="${LANE_Y + HEAD_H}" x2="${x + LANE_W - 12}" y2="${LANE_Y + HEAD_H}" stroke="${rule}"/>
`;
  lane.rows.forEach(([k, v], r) => {
    const y = LANE_Y + HEAD_H + 20 + r * ROW_H;
    svg += `<text class="k mono" x="${x + 14}" y="${y}">${line(k)}</text>
<text class="v" x="${x + 14}" y="${y + 17}">${line(v)}</text>
`;
  });
  if (lane.foot) {
    svg += `<text class="foot mono" x="${x + 14}" y="${LANE_Y + LANE_H + 24}">${line(lane.foot)}</text>\n`;
  }
  if (i < lanes.length - 1) {
    const ax = x + LANE_W + 2, ay = LANE_Y + LANE_H / 2;
    svg += `<path d="M ${ax} ${ay} L ${ax + LANE_GAP - 6} ${ay}" stroke="${accent}" stroke-width="2.5" marker-end="url(#arr)"/>\n`;
  }
});

svg += `<defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${accent}"/></marker></defs>
<text class="cap" x="${PAD}" y="${H - 40}">The git repo is the handoff: GitHub never holds a Cloudflare credential; Cloudflare never runs a model.</text>
<text class="cap" x="${PAD}" y="${H - 20}">A failed gate commits nothing — the deploy never triggers and last week's issue stays live. Diagram generated from site.config.json by bin/render-architecture.mjs.</text>
</svg>
`;

const out = join(ROOT, 'docs', 'architecture.svg');
writeFileSync(out, svg);
console.log(`rendered docs/architecture.svg for "${name}" (ZIP ${cfg.zip}, ${cfg.domain ? cfg.domain : 'workers.dev'})`);
